import {rosterProgress} from './roster.js';
import {memberCard} from './roster-view.js';
import {exportSnapshot} from './snapshot.js';
import {dayToken,verifyToken,visibleEvents,safeDisplay,thresholdProgress,stageProgress} from './progress.js';
import {parseUpdate,previewUpdate,clipboardCandidate,updateTemplate,refreshHandoff} from './updates.js';
import {authorizeUpdateReview,protectedOperations} from './operation-policy.js';
import {clone,uid,newCampaign,blankCharacter,preview,prepareCreation,prepareRestore,parseBackup,backup,summary,validateState} from './core.js';
import {openDB,allCampaigns,getCampaign,getPreference,setPreference,commit} from './db.js';
const $=s=>document.querySelector(s), app=$('#app'),modal=$('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nice=v=>typeof v==='object'?JSON.stringify(safeDisplay(v),null,2):String(v??'—');
const number=v=>Number(v).toLocaleString();
let campaigns=[],state=null,focus=null,tab='play',storage='Checking storage…',offline=false,dirty=false,saving=false,toastTimer,backupMark=null,refMarks={};
const channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('scroll-changes'):null;
const icons={updates:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',play:'M4 4h16v16H4z M8 9h8 M8 13h5',roster:'M4 5h16v14H4z M4 10h16 M10 5v14',reference:'M5 3h12l2 2v16H5z M8 8h8 M8 12h8 M8 16h5',journal:'M5 6h14 M5 12h14 M5 18h14',backup:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[k]}"/></svg>`;
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5000);}
function error(e){if(e instanceof SyntaxError)e=Error('Invalid JSON. No changes were saved.');const target=$('#dialog-error');if(target)target.textContent=e.message||String(e);else toast(e.message||String(e));}
function showModal(title,body,footer=''){modal.innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${esc(title)}</h2><button data-close aria-label="Close dialog">×</button></div>${body}<p class="error" id="dialog-error" role="alert"></p>${footer}`;dirty=false;if(!modal.open)modal.showModal();}
function closeModal(){if(saving)return;if(dirty&&!confirm('Discard these unsaved edits?'))return;dirty=false;modal.close();}
modal.addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeModal();});
modal.addEventListener('input',()=>{dirty=true;});
modal.addEventListener('cancel',e=>{e.preventDefault();closeModal();});
window.addEventListener('beforeunload',e=>{if(dirty||saving||updateDraft){e.preventDefault();e.returnValue='';}});
async function reload(id=state?.campaign_id){campaigns=await allCampaigns();const chosen=id||await getPreference('active-campaign');state=campaigns.find(c=>c.campaign_id===chosen)||campaigns[0]||null;if(state){validateState(state);focus=await getPreference(`focus:${state.campaign_id}`);if(!state.characters.some(c=>c.character_id===focus))focus=state.characters[0].character_id;backupMark=await getPreference(`backup:${state.campaign_id}`);refMarks=await getPreference(`references:${state.campaign_id}`)||{};}render();}
function selected(){return state.characters.find(c=>c.character_id===focus);}
function backupDue(){return !backupMark||backupMark.lineage!==state.lineage_id||state.current_revision-backupMark.revision>=10||Date.now()-Date.parse(backupMark.at)>7*86400000||state.sessions.some(s=>s.state==='closed'&&Date.parse(s.closed_at)>Date.parse(backupMark.at));}
function render(){
 app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="sidebar-top"><div class="brand"><img src="./icon.svg" alt="">Scroll</div><div class="campaign-control"><label for="campaign-select">Your campaign</label><select id="campaign-select" aria-label="Select campaign">${campaigns.map(c=>`<option value="${esc(c.campaign_id)}" ${state?.campaign_id===c.campaign_id?'selected':''}>${esc(c.display_name)}</option>`).join('')}<option value="__new">＋ New campaign</option></select></div></div><nav class="nav" aria-label="Campaign views">${[['play','Play'],['updates','DM updates'],['reference','Character'],['roster',state?.roster_config?.label||'Roster'],['journal','Journal'],['backup','Backups']].map(([key,label])=>`<button data-tab="${key}" class="${tab===key?'active':''}" ${tab===key?'aria-current="page"':''}>${icon(key)}<span>${esc(label)}</span></button>`).join('')}</nav><div class="sidebar-footer"><p class="eyebrow">Campaign ledger</p><p class="small muted">One operator. Your device.<br>Your campaign.</p></div></aside><main class="workspace"><header class="topbar"><p class="eyebrow">${state?esc(state.display_name):'Campaign companion'}</p><div class="badges"><span class="pill">${state?'Saved on this device':'Local storage'}</span><span class="pill">${offline?'Offline ready':'Preparing offline access'}</span></div></header>${state?view():welcome()}<p class="footer-note">${esc(storage)} · JSON exports are your backup.</p></main></div>`;
 $('#campaign-select').addEventListener('change',async e=>{if(e.target.value==='__new'){newCampaignDialog();render();return;}await setPreference('active-campaign',e.target.value);tab='play';await reload(e.target.value);});
 app.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();window.scrollTo(0,0);});
 const select=$('#character-select');if(select)select.onchange=async e=>{focus=e.target.value;await setPreference(`focus:${state.campaign_id}`,focus);render();};
 const importText=$('#update-text');if(importText)importText.oninput=()=>{updateDraft=importText.value;dirty=!!updateDraft;};const importFile=$('#update-file');if(importFile)importFile.onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1024*1024)throw Error('Update file must be under 1 MB.');reviewImport(await file.text());}catch(err){toast(err.message);}finally{e.target.value='';}};const search=$('#journal-search');if(search)search.oninput=()=>renderJournal(search.value);
}
function welcome(){return `<section class="welcome"><p class="eyebrow">A place for the facts</p><h1>Keep the story moving.</h1><div class="intro-rule"></div><p class="muted">Your calendar, characters, and confirmed numbers, together.<br>Saved locally. Available offline. Ready to copy back to your DM.</p><div class="welcome-grid"><div class="card sample"><p class="eyebrow">Continue an existing campaign</p><h2>Bring your opening state.</h2><p>Review the prepared foundation baseline, then save it on this device.</p><button class="primary" data-action="baseline">Review opening baseline</button><p class="small muted" style="margin:1rem 0 0">Use the supplied scroll-foundation-baseline.json file.</p></div><div class="card"><p class="eyebrow">Start fresh</p><h2>A new campaign.</h2><p class="muted">Choose your own calendar, resource names, and player characters.</p><button data-action="new">Create campaign</button><p class="small muted">Give your DM the file templates and instructions for any game.</p><button data-action="template-kit">Download DM template kit</button></div></div><div class="notice" style="margin-top:1.5rem">Paste or upload DM updates, review changes, then save. The calendar checks events; external roll results advance training.</div><button class="text-link" data-action="restore">Or restore a Scroll backup</button><section class="card"><h2>Viewing another player’s snapshot?</h2><p>Use the separate read-only trainer viewer. It never creates a campaign of record.</p><a class="button-link" href="./snapshot.html">Open trainer snapshot viewer</a></section></section>`;}
function heading(title,sub){return `<div class="title-row"><div><p class="eyebrow">${esc(sub)}</p><h1>${esc(title)}</h1></div><select id="character-select" aria-label="Focused player character" style="max-width:210px">${state.characters.map(c=>`<option value="${esc(c.character_id)}" ${focus===c.character_id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>`;}
function view(){if(tab==='roster')return rosterView();if(tab==='updates')return updatesView();if(tab==='reference')return referenceView();if(tab==='journal')return journalView();if(tab==='backup')return backupsView();return playView();}
function playView(){const c=selected(),next=state.level_thresholds[String(c.level+1)],session=state.sessions.find(s=>s.state==='open');return `${heading('At the table',state.system_label||'Your campaign')} <div class="play-grid"><div class="stack"><section class="card"><div class="character-head"><div class="identity"><div class="avatar" aria-hidden="true">${esc(c.name.slice(0,1))}</div><div><h2>${esc(c.name)}</h2><p class="small muted">Level ${number(c.level)}${c.player_note?` · ${esc(c.player_note)}`:''}</p></div></div><button data-action="numbers">Update state</button></div><div class="resources">${c.resources.length?c.resources.map(r=>`<div class="resource"><div class="resource-label">${esc(state.resources.find(d=>d.id===r.id).label)}</div><div class="big-number">${number(r.current)} <span>/ ${number(r.max)}</span></div><progress aria-label="${esc(r.id)} resource" max="${Math.max(1,r.max)}" value="${Math.min(Math.max(r.current,0),r.max)}"></progress>${r.current>r.max?'<p class="over-max">Current exceeds maximum</p>':''}</div>`).join(''):'<p class="muted">No numeric resources configured.</p>'}</div><div class="stats-row"><div><span class="small muted">Cumulative XP</span><strong class="stat-value">${number(c.xp_total)} <small>${typeof next==='number'?`/ ${number(next)}`:''}</small></strong><p class="small muted" style="margin:.4rem 0 0">${typeof next==='number'?(c.xp_total>=next?'Next level threshold reached. Review with your DM.':`${number(next-c.xp_total)} to level ${c.level+1}`):'Next level threshold unknown'}</p></div><div><span class="small muted">${esc(state.currency.label)}</span><strong class="stat-value">${number(c.currency_amount)}</strong><p class="small muted" style="margin:.4rem 0 0">Character balance</p></div></div></section>${quickEntry()}<section class="card calendar"><p class="eyebrow">Current ${esc(state.day_label.singular)}</p><div class="day-number">${String(state.current_day).padStart(3,'0')}</div><div class="day-token">${esc(dayToken(state)||'Calendar upgrade required')}</div><button class="primary" data-action="advance">Advance ${esc(state.day_label.singular)}</button><button class="quiet" data-action="correct">Correct calendar</button><p class="small muted">Every day has one token. Send it to your DM.</p>${state.scheduler?.remainder?'<div class="remainder"><p>Remainder pending</p><button class="primary" data-action="resume">Resume travel</button></div>':''}</section>${eventsCard()}<section class="card"><div class="section-head"><h2>Inventory</h2><button class="text-link" data-action="inventory">Manage items</button></div>${c.inventory.length?c.inventory.map(i=>`<div class="row"><div class="clip"><p>${esc(i.item)}</p>${i.notes?`<p class="small muted">${esc(i.notes)}</p>`:''}</div><span class="quantity">× ${number(i.qty)}</span></div>`).join(''):'<div class="empty">No items recorded.</div>'}</section>${sinceSession()}</div><aside class="stack right-column"><section class="card"><p class="eyebrow">Session</p><h2>${session?'In progress':'Ready when you are'}</h2><p class="small muted">${session?`Opened on ${esc(state.day_label.singular)} ${session.opening_day}. Copy state at any natural break.`:'Open a session to mark where play begins.'}</p>${session&&Date.now()-Date.parse(session.opened_at)>48*3600000?'<div class="notice">Open for over 48 hours. Close or abandon this session.</div>':''}<div class="stack"><button class="primary" data-action="import">Import DM update</button><button data-action="summary">Copy state for DM</button><button data-action="${session?'close-session':'open-session'}">${session?'Close session':'Open session'}</button>${session?'<button data-action="session-notes">Session notes</button><button class="text-link" data-action="abandon-session">Abandon session</button>':''}</div></section><section class="card subtle"><h3>Confirmed here. Pending with the DM.</h3><p class="small muted" style="margin:0">A copied summary confirms saved values. It does not erase damage, rewards, or time changes that haven’t been submitted yet.</p></section></aside></div>${backupDue()?`<div class="notice backup-strip"><span>${backupMark?'Time for a fresh backup.':'Save your first backup.'} Local storage alone is not a backup.</span><button data-action="export">Save backup</button></div>`:''}${state.pending_migration?migrationCard():''}`;}
function migrationCard(){return '<section class="card"><h2>Campaign upgrade</h2><p>Existing training and event records need their reviewed configuration. Hidden dates are never displayed.</p><button data-action="upgrade">Review campaign upgrade file</button>'+(!state.scheduler?'<button data-action="activate">Activate empty calendar</button>':'')+'</section>';}
function referenceView(){const c=selected();return heading(c.name,'Character · Level '+c.level)+(refMarks[c.character_id]!==c.reference_revision?'<p class="notice">Character reference update needed.</p>':'')+'<section class="card character-primary"><h2>Attributes</h2><div class="ref-grid">'+c.attributes.map(a=>'<div class="attribute"><span>'+esc(a.label)+'</span><strong>'+esc(a.value)+'</strong><span>'+esc(a.note||'')+'</span></div>').join('')+'</div></section>'+abilityList(c)+thresholdList(c)+'<details class="card"><summary>Identity &amp; personal notes</summary><p>'+esc(c.profile.concept)+'</p><p>'+esc(c.profile.motivation)+'</p>'+c.profile.details?.map(d=>'<p><strong>'+esc(d.key)+'</strong> '+esc(d.value)+'</p>').join('')+'<p class="ref-text">'+esc(c.profile.notes||'')+'</p></details><details class="character-management"><summary>Manage / export reference</summary><div class="actions"><button data-action="reference-edit">Edit reference</button><button data-action="reference-export">Export character reference</button><button data-action="add-character">Add character</button></div></details>';}
function journalView(){return `${heading('Audit journal','Every saved change')}<section class="card"><label for="journal-search">Search reasons, fields, or character IDs</label><input id="journal-search" type="search" placeholder="Search the journal"><div id="journal-list">${journalHTML('')}</div></section>`;}
function journalHTML(q){const list=state.journal.filter(j=>`${j.reason} ${j.field} ${j.character_id||''}`.toLowerCase().includes(q.toLowerCase())).slice().reverse();return list.length?`${list.length>100?'<p class="small muted">Showing the newest 100 matches. Full history is in the backup.</p>':''}${list.slice(0,100).map(j=>`<article class="journal-entry"><div class="section-head"><strong>${esc(j.reason)}</strong><span class="small muted">#${j.journal_seq}</span></div><p class="small muted">${esc(state.day_label.singular)} ${j.in_world_day} · ${esc(new Date(j.timestamp).toLocaleString())} · ${esc(j.source)}</p><p class="small">${esc(j.character_id?state.characters.find(c=>c.character_id===j.character_id)?.name:'Campaign')} / ${esc(j.field)}</p><details><summary class="small">View before and after</summary><pre class="journal-diff mono">Before: ${esc(nice(safeDisplay(j.from)))}\n\nAfter: ${esc(nice(safeDisplay(j.to)))}</pre></details></article>`).join('')}`:'<p class="empty">No matching changes.</p>';}
function renderJournal(q){$('#journal-list').innerHTML=journalHTML(q);}
function backupsView(){return `${heading('Keep a copy','Backup & recovery')}<div class="two-col"><section class="card"><p class="eyebrow">Export</p><h2>Your campaign, in one file.</h2><p class="muted">Includes every character, saved change, session, reference, and pending migration record.</p><button class="primary" data-action="export">Save JSON backup</button><p class="small muted" style="margin-top:1rem">${backupMark?`Last confirmed saved: ${esc(new Date(backupMark.at).toLocaleString())}`:'No backup confirmed saved yet.'}</p></section><section class="card"><p class="eyebrow">Restore</p><h2>Return to a saved copy.</h2><p class="muted">Review the backup before replacing its matching campaign. A recovery export is offered first.</p><button data-action="restore">Choose backup to restore</button></section><section class="card"><h2>Device storage</h2><p>${esc(storage)}</p><p class="small muted">Browser storage can be removed. Keep JSON backups in Files or another location you control.</p><p class="small muted">On iPhone: open the hosted app in Safari, use Share → Add to Home Screen → Open as Web App. Open it online once before relying on offline access.</p></section><section class="card"><h2>Campaign tools</h2><p class="small muted">Roll externally. Day advance checks the schedule; confirmed results update training. Hidden dates stay in storage and never appear in app views.</p><button data-action="summary">View confirmed state</button><button class="text-link" data-action="baseline">Review another opening baseline</button></section></div>`;}
function formFooter(label='Review changes'){return `<div class="dialog-footer"><button type="button" data-close>Cancel</button><button class="primary" type="submit">${label}</button></div>`;}
function formDialog(title,body,handler,label){showModal(title,`<form id="edit-form">${body}${formFooter(label)}</form>`);$('#edit-form').onsubmit=async e=>{e.preventDefault();try{await handler(new FormData(e.target));}catch(err){error(err);}};}
function diffValue(value,field,campaign){
 if(field==='resources'&&Array.isArray(value))return value.map(r=>((campaign.resources.find(d=>d.id===r.id)?.label)||r.id)+': '+r.current+' / '+r.max).join('\n');
 if(field==='attributes'&&Array.isArray(value))return value.map(a=>a.label+' ['+a.key+']: '+a.value+(a.note?' — '+a.note:'')).join('\n')||'No attributes';
 if(field==='inventory'&&Array.isArray(value))return value.map(i=>i.item+' × '+i.qty+(i.consumable?' (consumable)':'')+(i.notes?' — '+i.notes:'')).join('\n')||'No items';
 if(field==='sessions'&&Array.isArray(value))return value.map(s=>'Opened day '+s.opening_day+' · '+s.state+(s.closing_day!==null?' · ended day '+s.closing_day:'')).join('\n')||'No sessions';
 return nice(value);
}
function review(p,{create=false,after=null}={}){
 const closingWithoutAdvance=p.next.transactions.at(-1).operations.some(o=>o.op==='close_session')&&!state.sessions.find(x=>x.state==='open')?.advance_submitted;const travelling=p.next.transactions.at(-1).operations.some(o=>o.op==='advance_day');const diffs=expandResourceDiffs(p.diffs).filter(d=>!travelling||d.field!=='scheduler').map(d=>travelling&&['current_day','scheduler'].includes(d.field)?{...d,field:'Time advance',from:'Current day '+state.current_day,to:'Advance toward requested day '+p.next.transactions.at(-1).operations.find(o=>o.op==='advance_day').to_day+'. The reached day, token, and any remainder appear only after save.'}:d).filter(d=>d.field!=='reference_revision').map(d=>`<div class="diff-item"><strong class="small">${esc(d.character_id?p.next.characters.find(c=>c.character_id===d.character_id)?.name:'Campaign')} · ${esc(d.field.replaceAll('_',' '))}</strong>${d.reason?'<p class="small muted">'+esc(d.reason)+'</p>':''}<pre>${esc(d.field==='opening_baseline'?'No saved campaign':diffValue(d.from,d.field,p.next))}</pre><pre class="after">→ ${esc(d.field==='opening_baseline'?`${p.next.display_name}, day ${p.next.current_day}; ${p.next.characters.map(c=>`${c.name}, level ${c.level}, XP ${c.xp_total}`).join('; ')}; ${p.next.pending_migration?'pending migration records inactive':'no pending records'}`:diffValue(d.to,d.field,p.next))}</pre></div>`).join('');
 showModal('Review changes',`<p class="muted">${esc(p.reason)}</p>${p.next.transactions.at(-1).operations.some(o=>o.op==='resolve_event')?'<p class="notice">Resolve scheduled events in your primary campaign conversation, not a side conversation.</p>':''}${closingWithoutAdvance?'<p class="notice">Overdue time check: no advance_day was submitted this session. Confirm the calendar with your DM before closing.</p>':''}<div class="diff-list">${diffs}</div>${p.importEnvelope?.operations.some(o=>o.op==='set_attribute')?'<p class="notice">Changed attributes will need a reference export. Attribute notes are required in the same operation. Modifiers are stored literally.</p>':''}${protectedOperations(p.next.transactions.at(-1).operations).length?'<label class="check notice"><input id="protected-confirm" type="checkbox">I explicitly approve the listed protected changes / time skip. Dates remain hidden.</label>':''}<p class="small muted">Nothing changes until you confirm. All listed changes save together.</p>`,`<div class="dialog-footer"><button data-close>Cancel</button><button class="primary" id="confirm-save">Confirm & save</button></div>`);
 $('#confirm-save').onclick=async event=>{if(saving)return;if($('#protected-confirm')&&!$('#protected-confirm').checked){error(Error('Explicit approval is required for these protected operations.'));return;}saving=true;$('#confirm-save').disabled=true;try{if(p.importEnvelope||protectedOperations(p.next.transactions.at(-1).operations).length)authorizeUpdateReview(p,event);await commit(p,create);dirty=false;modal.close();await setPreference('active-campaign',p.campaign_id);await reload(p.campaign_id);channel?.postMessage(p.campaign_id);toast('Saved on this device');requestAnimationFrame(()=>{for(const el of document.querySelectorAll('.day-token,.identity,.threshold'))el.classList.add('ceremonial-beat');});if(after)await after();}catch(e){if(p.importEnvelope&&e.code==='STALE_COMMIT'){await reload(p.campaign_id);reviewImport(JSON.stringify(p.importEnvelope));}else error(e);const button=$('#confirm-save');if(button)button.disabled=false;}finally{saving=false;}};
}
function numbersDialog(){const c=clone(selected());formDialog(`Update ${c.name}`,`<p class="small muted">Enter confirmed values. Level and maximum changes are explicit; Scroll never levels up a character.</p><div class="form-grid"><label>Level<input name="level" type="number" min="1" step="1" required value="${c.level}"></label><label>Cumulative XP<input name="xp" type="number" min="0" step="1" required value="${c.xp_total}"></label><label>${esc(state.currency.label)}<input name="currency" type="number" step="1" required value="${c.currency_amount}"></label></div>${c.resources.map((r,i)=>`<div class="form-section"><h3>${esc(state.resources.find(d=>d.id===r.id).label)}</h3><div class="form-grid"><label>Current<input name="r${i}" type="number" step="1" required value="${r.current}"></label><label>Maximum<input name="m${i}" type="number" step="1" min="0" required value="${r.max}"></label></div></div>`).join('')}<label class="form-section">Reason<input name="reason" required value="Session state update"></label>`,f=>{c.level=Number(f.get('level'));c.xp_total=Number(f.get('xp'));c.currency_amount=Number(f.get('currency'));c.resources.forEach((r,i)=>{r.current=Number(f.get(`r${i}`));r.max=Number(f.get(`m${i}`));});review(preview(state,[{op:'set_character',character_id:c.character_id,character:c}],f.get('reason')));});}
function dayDialog(correct=false){formDialog(correct?'Correct the calendar':`Advance ${state.day_label.singular}`,`<p class="small muted">Currently ${esc(state.day_label.singular)} ${state.current_day}. ${correct?'This is a bookkeeping correction; it does not rewind the story.':'Confirm elapsed time before your DM narrates past it.'}</p><div class="notice">Travel stops at pre-generated cover points or due events. The reached day appears only after saving. Resume any remainder with one tap.</div><label class="check"><input type="checkbox" name="skip">Skip through all intervening days</label><label style="margin-top:1rem">${correct?'Correct day':'Advance to'}<input name="day" type="number" min="${correct?0:state.current_day+1}" step="1" required value="${correct?state.current_day:state.current_day+1}"></label><label>Reason<input name="reason" required ${correct?'placeholder="Explain the correction"':'value="Time elapsed"'}></label>`,f=>review(preview(state,[{op:correct?'correct_day':'advance_day',to_day:Number(f.get('day')),reason:String(f.get('reason')),skip_through:f.has('skip')}],f.get('reason')),{after:()=>copyDialog('Calendar saved',summary(state))}));}
function inventoryDialog(){const c=clone(selected());const draw=()=>{formDialog('Manage inventory',`<div id="items">${c.inventory.map((i,n)=>`<div class="form-section"><div class="form-grid"><label>Item<input name="item${n}" required value="${esc(i.item)}"></label><label>Quantity<input name="qty${n}" required type="number" min="0" step="1" value="${i.qty}"></label><label class="span">Notes<input name="notes${n}" value="${esc(i.notes||'')}"></label><label class="check"><input name="cons${n}" type="checkbox" ${i.consumable?'checked':''}>Consumable</label></div></div>`).join('')}</div><button id="add-item" type="button" style="margin:1rem 0">＋ Add item</button><p class="small muted">Set quantity to 0 to record an exhausted item. History is retained.</p><label>Reason<input name="reason" required value="Inventory update"></label>`,f=>{read(f);review(preview(state,[{op:'set_character',character_id:c.character_id,character:c}],f.get('reason')));});$('#add-item').onclick=()=>{read(new FormData($('#edit-form')));c.inventory.push({item:'',qty:1,consumable:false,notes:''});draw();dirty=true;};};const read=f=>{c.inventory=c.inventory.map((i,n)=>({item:String(f.get(`item${n}`)),qty:Number(f.get(`qty${n}`)),consumable:f.has(`cons${n}`),notes:String(f.get(`notes${n}`))}));};draw();}
function referenceDialog(add=false){const c=add?blankCharacter(state):clone(selected());formDialog(add?'Add player character':'Edit character reference',`<p class="small muted">Player characters only. Store reference details as written; Scroll does not interpret them.</p><div class="form-grid"><label>Name<input name="name" required value="${esc(c.name)}"></label><label>Player note<input name="player" value="${esc(c.player_note||'')}"></label><label class="span">Concept<textarea name="concept">${esc(c.profile.concept||'')}</textarea></label><label class="span">Motivation<textarea name="motivation">${esc(c.profile.motivation||'')}</textarea></label><label class="span">Notes<textarea name="notes">${esc(c.profile.notes||'')}</textarea></label></div><details class="form-section" ${add?'':'open'}><summary>Attributes and structured details</summary><p class="small muted">Edit ordered JSON lists. Values remain plain text or numbers; no formulas.</p><label>Attributes<textarea class="mono" name="attributes">${esc(JSON.stringify(c.attributes,null,2))}</textarea></label><p class="small muted">Example: [{"key":"speed","label":"Movement","value":30,"note":"ft"}]</p><label>Profile detail pairs<textarea class="mono" name="details">${esc(JSON.stringify(c.profile.details||[],null,2))}</textarea></label>${state.ability_slots_enabled?`<label>Ability slots<textarea class="mono" name="slots">${esc(JSON.stringify(c.ability_slots||[],null,2))}</textarea></label>`:''}</details><label class="form-section">Reason<input name="reason" required value="${add?'Add player character':'Update character reference'}"></label>`,f=>{c.name=String(f.get('name'));c.player_note=String(f.get('player'));c.profile={concept:String(f.get('concept')),motivation:String(f.get('motivation')),notes:String(f.get('notes')),details:JSON.parse(f.get('details'))};c.attributes=JSON.parse(f.get('attributes'));if(state.ability_slots_enabled)c.ability_slots=JSON.parse(f.get('slots'));review(preview(state,[{op:add?'add_character':'set_character',character_id:c.character_id,character:c}],f.get('reason')),{after:async()=>{focus=c.character_id;await setPreference(`focus:${state.campaign_id}`,focus);render();}});});}
function newCampaignDialog(){formDialog('Create your campaign',`<div class="form-grid"><label class="span">Campaign name<input name="name" required placeholder="Campaign name"></label><label class="span">System label (optional)<input name="system" placeholder="Your system or setting"></label><label>First character name<input name="character" required></label><label>Current day<input name="day" type="number" min="0" step="1" required value="1"></label><label>Time unit<input name="singular" required value="day"></label><label>Plural<input name="plural" required value="days"></label><label class="span">Calendar note<textarea name="calendar"></textarea></label><label class="span">Resource labels, separated by commas<input name="resources" placeholder="Your resource names"></label><label>Currency label<input name="currency" required value="Currency"></label><label class="check"><input name="slots" type="checkbox">Track ability slots</label><label class="span">XP boundaries by level (optional JSON)<textarea name="levels" class="mono">{}</textarea></label></div><p class="small muted">For example: {"2": 100, "3": "unknown"}. Set character numbers after creation.</p>`,f=>{const labels=String(f.get('resources')).split(',').map(s=>s.trim()).filter(Boolean);const s=newCampaign({display_name:String(f.get('name')),system_label:String(f.get('system')),character_name:String(f.get('character')),current_day:Number(f.get('day')),day_label:{singular:String(f.get('singular')),plural:String(f.get('plural'))},day_zero_note:String(f.get('calendar')),resources:labels.map((label,i)=>({id:`resource-${i+1}`,label})),currency:{id:'currency',label:String(f.get('currency'))},ability_slots_enabled:f.has('slots'),level_thresholds:JSON.parse(f.get('levels'))});review(prepareCreation(s,'Create campaign'),{create:true});});}
async function copyText(text){try{await navigator.clipboard.writeText(text);return true;}catch{return false;}}
function copyDialog(title,text,after=null,instructions='Copy this block at a natural break. Keep unsubmitted changes pending with the DM.'){showModal(title,`<p class="small muted">${esc(instructions)}</p><textarea id="copy-text" class="mono code" readonly aria-label="Copyable state">${esc(text)}</textarea>`,`<div class="dialog-footer"><button data-close>Done</button><button class="primary" id="copy-button">Copy block</button></div>`);$('#copy-button').onclick=async()=>{if(await copyText(text)){toast('Copied');if(after)await after();}else{$('#copy-text').focus();$('#copy-text').select();toast('Text selected. Use Copy from the selection menu.');if(after){$('#copy-button').textContent='I copied the reference';$('#copy-button').onclick=async()=>{await after();toast('Reference marked exported');};}}};}
function download(text,filename){const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function exportDialog(){const snapshot=clone(state),b=backup(snapshot),text=JSON.stringify(b,null,2),filename=`scroll-${snapshot.campaign_id}-day-${snapshot.current_day}-${new Date().toISOString().slice(0,10)}.json`;showModal('Save a campaign backup',`<p>${esc(snapshot.display_name)} · ${esc(snapshot.day_label.singular)} ${snapshot.current_day}</p><p class="small muted">Save the file to Files or another location you control. Confirm below after you’ve saved it.</p><div class="actions"><button class="primary" id="download-backup">Download JSON</button><button id="share-backup">Share / Save to Files</button></div>`,`<div class="dialog-footer"><button data-close>Done</button><button id="mark-backup" disabled>I saved the file</button></div>`);const downloaded=()=>{$('#mark-backup').disabled=false;};$('#download-backup').onclick=()=>{download(text,filename);downloaded();};const file=new File([text],filename,{type:'application/json'});if(!navigator.canShare?.({files:[file]}))$('#share-backup').hidden=true;else $('#share-backup').onclick=async()=>{try{await navigator.share({files:[file],title:'Scroll campaign backup'});downloaded();}catch(e){if(e.name!=='AbortError')error(e);}};$('#mark-backup').onclick=async()=>{await setPreference(`backup:${snapshot.campaign_id}`,{at:new Date().toISOString(),revision:snapshot.current_revision,lineage:snapshot.lineage_id});dirty=false;modal.close();await reload();toast('Backup marked saved');};}
function baselineDialog(){showModal('Review opening baseline',`<p class="small muted">Choose the prepared foundation baseline JSON. Choose a file, then tap Review selected file. Nothing is imported until you review and confirm.</p><label>Foundation baseline file<input class="file-input" type="file" id="baseline-file" accept=".json,application/json"></label><p id="baseline-status" class="small muted" role="status">No file selected.</p>`,`<div class="dialog-footer"><button data-close>Cancel</button><button class="primary" id="review-baseline" disabled>Review selected file</button></div>`);const input=$('#baseline-file'),button=$('#review-baseline');input.onchange=()=>{button.disabled=!input.files.length;$('#dialog-error').textContent='';$('#baseline-status').textContent=input.files.length?'File selected. Tap Review selected file to validate and continue.':'No file selected.';};button.onclick=async()=>{const file=input.files[0];if(!file)return;button.disabled=true;input.disabled=true;$('#dialog-error').textContent='';$('#baseline-status').textContent='Validating file…';try{if(file.size>20*1024*1024)throw Error('File is too large.');let packet;try{packet=JSON.parse(await file.text());}catch{throw Error('This file is not valid JSON. Choose the foundation baseline JSON file and try again.');}if(packet.format!=='scroll-foundation-baseline'||packet.version!==1||packet.campaign_id!==packet.state?.campaign_id)throw Error('Choose the prepared Scroll foundation baseline JSON.');const s=clone(packet.state);s.lineage_id=uid();validateState(s);if(s.current_revision!==0||s.journal.length||s.transactions.length)throw Error('This file contains saved campaign history. Use Backups → Restore for an existing campaign.');if(campaigns.some(c=>c.campaign_id===s.campaign_id))throw Error('This campaign is already on this device. Use Backups → Restore to recover a saved backup; an opening baseline cannot replace it.');formDialog('Approve foundation baseline',`<p><strong>${esc(s.display_name)}</strong> · ${esc(s.day_label.singular)} ${s.current_day}</p>${s.characters.map(c=>`<div class="card subtle"><h3>${esc(c.name)} · Level ${c.level}</h3><p>XP ${number(c.xp_total)} · ${esc(s.currency.label)} ${number(c.currency_amount)}</p><p>${c.resources.map(r=>`${esc(s.resources.find(x=>x.id===r.id).label)} ${r.current}/${r.max}`).join(' · ')}</p><p class="small muted">${c.inventory.length} inventory rows · ${c.attributes.length} attributes</p></div>`).join('')}<div class="notice" style="margin:1rem 0">${s.scheduler&&!s.pending_migration?'Training baselines and the frozen calendar are included. Hidden event dates remain concealed. Trigger-chained records still require DM adjudication.':'Training baselines are retained. Event scheduling still needs the reviewed campaign upgrade.'}</div><label>Approval reason<input name="reason" required placeholder="Why this opening state is approved"></label>`,f=>review(prepareCreation(s,String(f.get('reason'))),{create:true}),'Review changes');}catch(err){error(err);if(modal.contains(button)){$('#baseline-status').textContent='Nothing imported. Choose another file or retry after correcting it.';}}finally{if(modal.contains(button)){button.disabled=false;input.disabled=false;}}};}
function restoreDialog(){showModal('Restore a backup',`<p class="small muted">Choose a complete Scroll backup. The matching campaign will be replaced only after review; other campaigns remain intact.</p><label>Backup file<input class="file-input" id="restore-file" type="file" accept=".json,application/json"></label>`);$('#restore-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>20*1024*1024)throw Error('Backup exceeds the 20 MB limit.');const b=parseBackup(await file.text()),current=await getCampaign(b.campaign_id);formDialog('Review recovery',`<p><strong>${esc(b.state.display_name)}</strong> · ${esc(b.state.day_label.singular)} ${b.state.current_day}</p><p class="small muted">${b.state.characters.length} characters, ${b.state.journal.length} historical changes. Exported ${esc(b.exported_at)}.</p>${current?'<div class="notice"><p>Save a recovery copy of the current campaign before replacing it.</p><button type="button" id="recovery-export">Export current campaign</button></div><label class="check" style="margin:1rem 0"><input name="recovery" type="checkbox" required>I saved a recovery copy or deliberately choose to proceed without one.</label>':'<p class="small muted">This campaign is not on this device yet.</p>'}<label>Restore reason<input name="reason" required placeholder="Explain why this backup is being restored"></label>`,f=>review(prepareRestore(b,current,String(f.get('reason')))));if(current)$('#recovery-export').onclick=()=>download(JSON.stringify(backup(current),null,2),`scroll-recovery-${current.campaign_id}.json`);}catch(err){error(err);}};}
function migrationDialog(){showModal('Migration status','<p>Hidden dates are stored, never displayed. Use the campaign upgrade file to confirm training and scheduling rules.</p><button data-action="upgrade">Review campaign upgrade</button>');}
app.addEventListener('click',async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;try{switch(action){case 'roster-add':rosterEdit();break;case 'roster-edit':rosterEdit(e.target.closest('[data-member]').dataset.member);break;case 'roster-hp':rosterCounter(e.target.closest('[data-member]').dataset.member);break;case 'roster-pp':rosterCounter(e.target.closest('[data-member]').dataset.member,e.target.closest('[data-move]').dataset.move);break;case 'roster-move':rosterMove(e.target.closest('[data-member]').dataset.member,e.target.closest('[data-move]')?.dataset.move);break;case 'roster-box':{const m=ownedMember(e.target.closest('[data-member]').dataset.member),reason=m.status==='active'?'Move roster member to box':'Activate roster member';review(preview(state,[{op:'set_roster_status',character_id:focus,roster_id:m.roster_id,status:m.status==='active'?'boxed':'active',reason}],reason));break;}case 'roster-config':rosterConfig();break;case 'trainer-snapshot':trainerSnapshotDialog();break;case 'template-kit':await templateKitDialog();break;case 'use-item':{const item=e.target.closest('[data-item]').dataset.item;review(preview(state,[{op:'adjust_inventory',character_id:focus,item,delta:-1,reason:'Used consumable'}],'Used consumable'));break;}case 'resume':{const target=state.scheduler?.remainder?.target_day;if(!target)break;const p=preview(state,[{op:'advance_day',to_day:target,reason:'Resume travel'}],'Resume travel');await commit(p);await reload();channel?.postMessage(state.campaign_id);copyDialog('Advanced to day '+state.current_day+(state.scheduler.remainder?' · remainder pending':''),summary(state));break;}case 'upgrade':upgradeDialog();break;case 'activate':review(preview(state,[{op:'activate_scheduler'}],'Activate full calendar'));break;case 'quick':quickDialog();break;case 'session-notes':notesDialog();break;case 'resolve':resolveDialog(e.target.closest('[data-event]').dataset.event);break;case 'threshold-dc':dcDialog(e.target.closest('[data-threshold]').dataset.threshold);break;case 'delivery':review(preview(state,[{op:'record_delivery',reason:'delivered'}],'Record handoff delivery'));break;case 'verify-token':tokenDialog();break;case 'import':tab='updates';render();break;case 'review-import':reviewImport($('#update-text').value);break;case 'clipboard':checkClipboard(true);break;case 'dm-guide':copyDialog('Instructions for your DM',dmInstructions());break;case 'new':newCampaignDialog();break;case 'baseline':baselineDialog();break;case 'restore':restoreDialog();break;case 'numbers':numbersDialog();break;case 'inventory':inventoryDialog();break;case 'advance':dayDialog();break;case 'correct':dayDialog(true);break;case 'reference-edit':referenceDialog();break;case 'add-character':referenceDialog(true);break;case 'migration':migrationDialog();break;case 'export':exportDialog();break;case 'summary':copyDialog('Confirmed state for the DM',summary(state));break;case 'reference-export':{const c=clone(selected()),campaignID=state.campaign_id;copyDialog('Character reference',JSON.stringify({format:'scroll-character-reference',version:1,campaign_id:campaignID,character_id:c.character_id,name:c.name,player_note:c.player_note,attributes:c.attributes,profile:c.profile,ability_slots:c.ability_slots},null,2),async()=>{const marks=await getPreference(`references:${campaignID}`)||{};marks[c.character_id]=c.reference_revision;await setPreference(`references:${campaignID}`,marks);await reload();});break;}case 'open-session':review(preview(state,[{op:'open_session'}],'Open session'));break;case 'close-session':review(preview(state,[{op:'close_session'}],'Close session'),{after:exportDialog});break;case 'abandon-session':formDialog('Abandon session','<label>Reason<input name="reason" required placeholder="Explain why this session is abandoned"></label>',f=>review(preview(state,[{op:'abandon_session'}],String(f.get('reason')))));break;}}catch(err){error(err);}});
async function storageStatus(){try{if(!navigator.storage?.persist){storage='Persistent storage unavailable';return;}const prior=await getPreference('persistence-requested');let granted=await navigator.storage.persisted();if(!prior&&!granted){granted=await navigator.storage.persist();await setPreference('persistence-requested',true);}storage=granted?'Persistent storage granted':'Persistent storage not granted';}catch{storage='Persistent storage unavailable';}}
channel?.addEventListener('message',async()=>{if(modal.open){toast('Another tab saved changes. Your next save will recheck them.');return;}await reload();});
async function start(){try{if(localStorage.getItem('scroll-viewer-mode')==='1'){location.replace('./snapshot.html');return;}await openDB();await storageStatus();await reload();void checkClipboard(false);if('serviceWorker'in navigator){try{const registration=await navigator.serviceWorker.register('./sw.js');const updateNotice=()=>{if(registration.waiting)toast('Update ready. Save edits, then close all Scroll windows and reopen.');};updateNotice();registration.addEventListener('updatefound',()=>registration.installing?.addEventListener('statechange',updateNotice));await navigator.serviceWorker.ready;offline=true;render();}catch{toast('Offline caching is unavailable. Keep this page online.');}}const context=document.modelContext;if(context?.registerTool){Promise.resolve(context.registerTool({name:'read_scroll_confirmed_state',description:'Read the focused campaign’s confirmed campaign state. Does not apply pending DM changes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw Error('Expected an empty object.');if(!state)throw Error('No campaign is open.');return JSON.parse(summary(state));}})).catch(()=>{});}}catch(e){app.innerHTML=`<main class="loading"><h1>Unable to open storage</h1><p>${esc(e.message)}</p><p>Try a normal Safari window with storage enabled. Existing saved data has not been replaced.</p><button id="retry">Try again</button></main>`;$('#retry').onclick=()=>location.reload();}}
let updateDraft='',clipboardBusy=false,clipboardBlocked=false,offeredClipboard=null;

function updatesView(){return heading('Updates from your DM','Paste · Upload · Review')+(state.characters.some(c=>refMarks[c.character_id]!==c.reference_revision)?'<div class="notice reference-reminder">Character reference update needed. Export changed character references for your DM’s project document. <button data-tab="reference">Open character reference</button></div>':'')+`<div class="two-col"><section class="card"><h2>Bring the changes here.</h2><p class="muted">Paste a JSON update or choose its file. Both use the same validation and review.</p><label for="update-text">DM update block</label><input type="password" autocomplete="off" id="update-text" class="mono" placeholder="Paste update; contents stay concealed" value="${esc(updateDraft)}"><p class="small muted">Pasted contents are concealed so hidden dates cannot appear. The preview shows readable permitted changes.</p><div class="actions" style="margin-top:1rem"><button class="primary" data-action="review-import">Review update</button><button data-action="clipboard">Check clipboard</button></div><label class="file-input">Or choose an update file<input id="update-file" type="file" accept=".json,.txt,.md,application/json,text/plain,text/markdown"></label><p class="small muted">${clipboardBlocked?'This browser requires a tap or Paste action to read the clipboard.':'When you return to Scroll, a valid clipboard update is offered for review when browser permissions allow.'}</p></section><aside class="stack"><section class="card coastal"><h2>One exchange. One save.</h2><ol><li>Copy the latest state and instructions to your DM.</li><li>Ask for only changes that are still pending.</li><li>Import the update and confirm the preview.</li><li>Paste the receipt back to your DM.</li></ol><div class="stack"><button data-action="summary">Copy state for DM</button><button data-action="dm-guide">Copy DM instructions</button><button data-action="template-kit">Download DM template kit</button></div></section><section class="notice"><strong>Always under human control</strong><p>DC changes, event scheduling and resolution require explicit approval in addition to the import preview. Roll-log and journal writes remain unavailable. Future transports cannot bypass approval.</p></section><section class="card"><h3>Time changes</h3><p class="small muted">Submit elapsed time before narrating beyond the reached day. Every day emits a token; unresolved event IDs remain on Play.</p></section></aside></div>`;}
function reviewImport(text){try{const p=previewUpdate(state,text);if(p.status==='already_applied'){copyDialog('Already applied — no changes',JSON.stringify({format:'scroll-update-status',version:1,status:'already_applied',campaign_id:state.campaign_id,lineage_id:state.lineage_id,current_revision:state.current_revision,current_day:state.current_day,original_receipt:p.receipt},null,2));return;}review(p,{after:()=>{updateDraft='';dirty=false;copyDialog(p.receipt.status==='interrupted'?'Time committed · effects need DM revision':'Update saved · receipt for DM',JSON.stringify(safeDisplay(p.receipt),null,2));}});}catch(e){if(e.interruption){copyDialog('Revise time advance — nothing applied',JSON.stringify(e.interruption,null,2));}else if(e.refresh){copyDialog('Refresh needed — nothing applied',refreshHandoff(e.refresh),null,'Copy this whole message to your primary campaign DM. It includes the request to regenerate the pending update and your current state. Bring the regenerated update back here for review; do not edit IDs by hand.');const note=document.createElement('p');note.className='notice';note.textContent=e.message;modal.insertBefore(note,modal.children[1]);}else{showModal('Update not applied','<p class="error">'+esc(e.message)+'</p><p class="small muted">No part of this update was saved. Correct it with your DM and try again.</p>');}}}
async function checkClipboard(explicit=false){
 if(!state||clipboardBusy||saving||modal.open||document.visibilityState==='hidden')return;
 clipboardBusy=true;
 try{
  if(!navigator.clipboard?.readText)throw Error('Clipboard access unavailable');
  const text=await Promise.race([navigator.clipboard.readText(),new Promise((_,reject)=>setTimeout(()=>reject(Error('Clipboard access timed out')),1800))]);
  if(!state||saving||modal.open||document.visibilityState==='hidden')return;
  clipboardBlocked=false;
  if(explicit){if(text.trim())reviewImport(text);else toast('The clipboard is empty. Paste an update or choose its file.');return;}
  const candidate=clipboardCandidate(text,state);if(!candidate)return;
  const key=JSON.stringify(candidate);if(key===offeredClipboard)return;offeredClipboard=key;
  const host=document.createElement('div');host.id='clipboard-offer';host.className='notice clipboard-offer';
  host.innerHTML='<span>A DM update for this campaign is on your clipboard.</span><div class="actions"><button id="review-clipboard" class="primary">Review update</button><button id="dismiss-clipboard">Dismiss</button></div>';
  $('#clipboard-offer')?.remove();$('.workspace').prepend(host);
  $('#review-clipboard').onclick=()=>{host.remove();reviewImport(JSON.stringify(candidate));};$('#dismiss-clipboard').onclick=()=>host.remove();
 }catch{clipboardBlocked=true;if(explicit){tab='updates';render();toast('Use Paste in the update field, or choose a file. Clipboard access is restricted here.');}}
 finally{clipboardBusy=false;}
}
window.addEventListener('focus',()=>{void checkClipboard(false);});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')void checkClipboard(false);});
function dmInstructions(){return DM_AGREEMENT+"\nOwned roster (generic, trainer-scoped): configure_roster(label); add_roster_member(member); set_roster_member(member); set_roster_status(roster_id,status); adjust_roster_hp(roster_id,delta); adjust_move_pp(roster_id,move_id,delta); award_roster_xp(roster_id,delta); set_roster_level_threshold(level,cumulative_xp). All need character_id and reason. The owner must match owner_character_id; ownership cannot be changed by an edit. Members contain roster_id,owner_character_id,status,species,nickname,level,xp_total,resources:[{id:\"hp\",current,max}], six stats:[{key,label,value}], moves:[{move_id,name,type,category,power,accuracy,pp_current,pp_max,effect}], ability,bond (named band),held_item (text/null),status_condition (null or {name,duration_remaining,duration_unit}). Preserve unchanged fields and stable IDs in complete member replacements. Roster XP thresholds are separate from trainer thresholds. No automatic level-up, ability roll, duration tick or held-item inventory transfer. For details use ROSTER-AND-SNAPSHOTS.md in the template kit.\nTrainer snapshots are exported by Scroll for one owner and loaded in its separate read-only viewer. They are not baselines, backups or DM updates. Never attach campaign history, other owners or hidden schedule data to a snapshot.\n"+'\n\n'+JSON.stringify(updateTemplate(state),null,2)+'\n\nCURRENT CONFIRMED STATE\n'+summary(state);}



function expandResourceDiffs(diffs){return diffs.flatMap(d=>{if(d.field!=='resources'||!Array.isArray(d.from)||!Array.isArray(d.to))return [d];return d.to.flatMap(r=>{const old=d.from.find(x=>x.id===r.id);return ['current','max'].filter(k=>old?.[k]!==r[k]).map(k=>({...d,field:k+' '+(state?.resources.find(x=>x.id===r.id)?.label||r.id),from:old?.[k]??null,to:r[k]}));});});}
function quickEntry(){return '<section class="card"><h2>Quick entry</h2><div class="actions"><button data-action="quick">'+esc(state.currency.label)+' ±</button>'+selected().inventory.filter(i=>i.consumable).map(i=>'<button data-action="use-item" data-item="'+esc(i.item)+'" '+(i.qty<1?'disabled':'')+'>−1 '+esc(i.item)+'</button>').join('')+'</div></section>';}
function quickDialog(){const c=selected();formDialog('Quick entry','<label>'+esc(state.currency.label)+' change<input type="number" step="1" name="currency" value="0"></label>'+c.inventory.filter(i=>i.consumable).map((i,n)=>'<label>'+esc(i.item)+' change<input type="number" name="item'+n+'" step="1" value="0"></label>').join('')+'<label>Reason<input name="reason" required value="Spending / supplies"></label>',f=>{const reason=String(f.get('reason')),ops=[];if(Number(f.get('currency')))ops.push({op:'adjust_currency',character_id:focus,delta:Number(f.get('currency')),reason});c.inventory.filter(i=>i.consumable).forEach((i,n)=>{if(Number(f.get('item'+n)))ops.push({op:'adjust_inventory',character_id:focus,item:i.item,delta:Number(f.get('item'+n)),reason});});review(preview(state,ops,reason));});}
function sinceSession(){const last=state.sessions.filter(s=>s.state==='closed').at(-1);const list=state.journal.filter(j=>(!last||j.timestamp>last.closed_at)&&j.field!=='opening_baseline');return '<details class="card"><summary>Since last session · '+list.length+' changes</summary>'+list.slice(-50).reverse().map(j=>'<p>'+esc(j.reason)+' · '+esc(j.field.replaceAll('_',' '))+'</p><pre class="journal-diff">'+esc(j.field==='scheduler'?'Calendar checked; hidden dates concealed':nice(j.from)+' → '+nice(j.to))+'</pre>').join('')+(last?.notes?'<h3>Last session notes</h3><p class="ref-text">'+esc(last.notes)+'</p>':'')+'</details>';}
function notesDialog(){const session=state.sessions.find(x=>x.state==='open');formDialog('Session notes','<label>Notes<textarea name="notes">'+esc(session.notes||'')+'</textarea></label>',f=>review(preview(state,[{op:'set_session_notes',session_id:session.session_id,notes:String(f.get('notes'))}],'Update session notes')));}
function eventsCard(){const events=visibleEvents(state),chains=(state.scheduler?.events||[]).filter(e=>e.selection_rule==='trigger_chain'&&e.state==='scheduled');return '<section class="card"><h2>Day handoff</h2><p class="small muted">'+(events.length?'DM handling required':'No unresolved event IDs')+'</p>'+events.map(e=>'<div class="row"><strong class="mono">'+esc(e.id)+'</strong><button data-action="resolve" data-event="'+esc(e.id)+'">Resolve</button></div>').join('')+(chains.length?'<p class="notice">'+chains.length+' trigger-chained record needs DM adjudication. No date has been invented; automatic chain triggers are not supported.</p>':'')+'<button data-action="summary">Copy token &amp; state</button><button data-action="verify-token">Verify token</button>'+(events.length?'<button data-action="delivery">Mark handed to DM</button>':'')+'</section>';}
function resolveDialog(eventID){review(preview(state,[{op:'resolve_event',event_id:eventID,reason:'resolved'}],'resolved'));}
function tokenDialog(){formDialog('Verify day token','<label>Token<input name="token" required autocomplete="off"></label>',f=>{showModal('Token verification','<p>'+ (verifyToken(state,String(f.get('token')).trim())?'Valid token for this campaign.':'Token does not match. Check for a typing error.')+'</p>');},'Verify');}
function abilityList(c){if(!state.ability_slots_enabled)return '';return '<section class="card"><h2>Abilities</h2>'+c.ability_slots.map(slot=>'<div class="ability-slot"><p class="eyebrow">Slot '+slot.index+' · '+esc(slot.name||'Open — reserved for abilities acquired in play')+'</p>'+(slot.applications?.length?slot.applications.map(a=>{if(typeof a==='string')return '<p>'+esc(a)+' <span class="pill">Status needs explicit confirmation</span></p>';const t=state.thresholds?.find(t=>t.id===a.threshold_id&&t.character_id===c.character_id);return '<details class="ability"><summary><span class="ability-name">'+esc(a.name)+'</span><span class="status '+esc(a.status)+'">'+esc({locked:'Locked',trained_unquantified:'Trained · not yet quantified',in_development:'In development'}[a.status])+'</span><span class="ability-cost">'+esc(a.cost)+'</span><span class="ability-effect">'+esc(a.effect)+'</span>'+(a.status==='in_development'&&t?'<span class="inline-progress">'+progressLabel(t)+'</span>':'')+'</summary><dl><dt>Cost</dt><dd>'+esc(a.cost)+'</dd><dt>Range / action</dt><dd>'+esc(a.range)+'</dd><dt>Effect</dt><dd>'+esc(a.effect)+'</dd><dt>Notes</dt><dd>'+esc(a.notes)+'</dd></dl>'+(a.status==='in_development'&&t?progressHTML(t):'')+'</details>';}).join(''):'<p class="small muted">Open slot</p>')+'</div>').join('')+'</section>';}
function progressLabel(t){const p=thresholdProgress(t);if(p.complete)return 'Complete';const i=p.current_stage_index,g=t.stages[i],v=p.stages[i];return esc(g.consecutive_required?v.streak:v.successes)+' / '+g.required+(g.consecutive_required?' consecutive':' successes');}
function progressHTML(t){const p=thresholdProgress(t);return '<p class="status '+(p.complete?'locked':'in_development')+'">'+(p.complete?'Complete':'In progress')+'</p>'+t.stages.map((g,i)=>{const v=p.stages[i];return '<p>Stage '+(i+1)+' · '+esc(g.consecutive_required?v.streak:v.successes)+' / '+g.required+(g.consecutive_required?' consecutive':' successes')+'</p><progress max="'+g.required+'" value="'+(g.consecutive_required?v.streak:v.successes)+'" aria-label="'+esc(t.label)+' stage '+(i+1)+'"></progress>';}).join('');}
function thresholdList(c){return '<section class="card"><h2>Training thresholds</h2>'+(state.thresholds||[]).filter(t=>t.character_id===c.character_id).map(t=>'<details class="threshold"><summary>'+esc(t.label)+' <span class="inline-progress">'+progressLabel(t)+'</span></summary>'+progressHTML(t)+'<p class="small mono">'+esc(t.id)+'</p>'+t.stages.map(g=>'<p>Stage '+g.stage_index+' · DC '+esc(g.dc_revisions.at(-1)?.dc??'unknown')+' · <span class="mono">'+esc(g.dc_revisions.at(-1)?.revision_id||'not set')+'</span></p>').join('')+'<button data-action="threshold-dc" data-threshold="'+esc(t.id)+'">Set / amend DC</button></details>').join('')+'</section>';}
function dcDialog(thresholdID){formDialog('Explicit DC amendment','<label>Stage index<input type="number" name="stage" min="0" value="0" required></label><label>DC<input type="number" name="dc" required></label><label>Reason<input name="reason" required></label>',f=>review(preview(state,[{op:'set_threshold_dc',character_id:focus,threshold_id:thresholdID,stage_index:Number(f.get('stage')),dc:Number(f.get('dc')),reason:String(f.get('reason'))}],String(f.get('reason')))));}
function upgradeDialog(){showModal('Review campaign upgrade','<p>Choose the campaign-specific upgrade JSON. It uses this campaign’s current revision and the normal reviewed transaction. Hidden dates are never displayed.</p><label>Upgrade file<input type="file" id="upgrade-file" accept=".json,application/json"></label>');$('#upgrade-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1024*1024)throw Error('Upgrade file too large.');let packet;try{packet=JSON.parse(await file.text());}catch{throw Error('Invalid upgrade JSON.');}if(packet.format!=='scroll-campaign-upgrade'||packet.version!==1||packet.campaign_id!==state.campaign_id||!Array.isArray(packet.operations))throw Error('Upgrade belongs to another campaign or format.');const prior=state.transactions.find(t=>t.update?.update_id===packet.update_id);const operations=prior?.update.request_operations||packet.operations.filter(o=>!(state.scheduler&&o.op==='activate_scheduler'));reviewImport(JSON.stringify({...updateTemplate(state),update_id:packet.update_id,operations}));}catch(err){error(err);}};}
const DM_AGREEMENT=`SCROLL — CONSOLIDATED BUILD
Resolve scheduled events in your primary campaign conversation, not a side conversation.
Roll externally. DC-before-roll evidence lives in the ordered chat transcript. Scroll never rolls dice or writes a roll log.
Keep all pending changes until an accepted receipt. Return strict scroll-session-update JSON with unique update_id and the latest campaign_id, lineage_id, base_revision. On stale state, use the copyable refresh; never ask the player to hand-edit IDs.
Every operation needs a reason. Character operations need character_id.
Automatable vocabulary (current transport still previews and confirms):
adjust_resource(resource,delta), award_xp(delta), adjust_currency(delta), adjust_inventory(item,delta,consumable for new items), advance_day(to_day).
set_resource_max(resource,value): absolute; does not change current.
set_level(value), set_xp(value), set_currency(value): absolute.
set_attribute(key,value,note): note REQUIRED, including an explicit empty string if intended. No calculated modifiers.
set_level_threshold(level,cumulative_xp): absolute cumulative XP or "unknown". Undefined future levels stay undefined until provided.
set_ability_detail(slot_index,application_name,status,cost?,range?,effect?,notes?,slot_name?,threshold_id?): status MUST be locked | trained_unquantified | in_development. Development requires linked threshold_id. Explicit unpinned fields are "not yet quantified". Can fill existing open slots.
log_threshold_attempt(threshold_id,stage_index,result,dc_revision_id): success or failure from an external roll; exact recorded DC revision, current stage only. Retry the same update_id; never duplicate the same attempt under a new ID.
Protected, explicit extra human approval on each batch: schedule_event(visibility,eligible_from_day,must_fire_by_day,selection_rule; optional import_historical), amend_event_date(event_id plus full schedule), resolve_event(event_id), set_threshold_dc(threshold_id,stage_index,dc). Hidden events use neutral reasons only: created, imported, date_amended, resolved. No hidden narrative. Random event IDs are assigned by Scroll. Dates live in campaign storage and backups, never in app displays.
The day is the only event trigger. Send advance_day before narrating past it. Every day has one pre-generated token with a typo checksum. Send current token with every day handoff. Triggered event IDs persist until explicitly resolved. Event IDs have no ordering meaning.
Multi-day travel commits to the first due or pre-generated cover stop. Cover stops are independently fixed across the whole calendar at creation (~1/3 of days); they camouflage timing but do not guarantee statistical indistinguishability. No stop date is previewed. A pending remainder can be resumed with one tap. Add effective_day to day-scoped operations. If a stop precedes any operation’s effective_day, or effects are unscoped, time commits alone and ALL non-time effects remain pending. The interruption receipt names the day reached. Revise the non-time effects under a new update_id. Original retries return the same receipt and never replay time. Explicit skip_through:true requires extra human approval.
The receipt includes every crossed day's token and every unresolved opaque ID in current state. Attribute/ability changes require refreshed reference export. In-development progress never silently changes an ability's explicit status.
No journal edits or roll-log writes are accepted.`;
start();


async function templateKitDialog(){
 showModal('DM template kit','<p>Preparing the bundled kit…</p>');
 try{const response=await fetch('./scroll-dm-template-kit.zip');if(!response.ok)throw Error('The template kit is not available yet. Open Scroll online once, wait for Offline ready, then try again.');const blob=await response.blob();if(!modal.open)return;
 const file=new File([blob],'scroll-dm-template-kit.zip',{type:'application/zip'});
 showModal('DM template kit','<p>Give this ZIP to your DM, or unzip it in Files. It contains instructions, new-campaign and update examples, and the operation reference.</p><p class="notice">Examples use fictional values. Have your DM fill them in before import. Move an existing campaign using a Scroll backup.</p><p class="small muted">Bundled with Scroll and available offline after Offline ready. No campaign data is included.</p><div class="actions"><button class="primary" id="download-kit">Download ZIP</button><button id="share-kit">Share / Save to Files</button></div>','<div class="dialog-footer"><button data-close>Done</button></div>');
 $('#download-kit').onclick=()=>{const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=file.name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);};
 const share=$('#share-kit');share.hidden=!navigator.canShare?.({files:[file]});share.onclick=async()=>{try{await navigator.share({files:[file],title:'Scroll DM template kit'});}catch(e){if(e.name!=='AbortError')error(e);}};
 }catch(e){if(modal.open)error(e);}
}

function rosterView(){const members=(state.roster||[]).filter(m=>m.owner_character_id===focus);return heading(state.roster_config?.label||'Roster','Owned by '+selected().name)+`<section class="card"><div class="actions"><button class="primary" data-action="roster-add">Add roster member</button><button data-action="trainer-snapshot">Export snapshot for ${esc(selected().name)}</button></div><p class="small muted">Only this trainer’s members are shown. HP and PP changes are reviewed and journaled.</p><details><summary>Roster settings &amp; shared XP table</summary><p class="small muted">One curve for all roster members, separate from trainer XP. No automatic leveling.</p><button data-action="roster-config">Edit label and XP thresholds</button><pre class="mono">${esc(JSON.stringify(state.roster_level_thresholds||{},null,2))}</pre></details></section><h2>Active team</h2>${members.filter(m=>m.status==='active').map(m=>memberCard(m,rosterProgress(m,state.roster_level_thresholds),{editable:true})).join('')||'<p class="empty">No active members.</p>'}<details class="card"><summary>Boxed members · ${members.filter(m=>m.status==='boxed').length}</summary>${members.filter(m=>m.status==='boxed').map(m=>memberCard(m,rosterProgress(m,state.roster_level_thresholds),{editable:true})).join('')}</details>`;}
function ownedMember(id){const m=state.roster?.find(m=>m.roster_id===id&&m.owner_character_id===focus);if(!m)throw Error('Choose a roster member owned by this trainer.');return clone(m);}
function rosterEdit(id){const old=id?ownedMember(id):null;const m=old||{roster_id:uid(),owner_character_id:focus,status:'active',species:'',nickname:'',level:1,xp_total:0,resources:[{id:'hp',current:'',max:''}],stats:['HP','Attack','Defense','Special attack','Special defense','Speed'].map((label,i)=>({key:'stat-'+i,label,value:''})),moves:[],ability:'',bond:'',held_item:null,status_condition:null};const field=(label,name,value,type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'step="1"':''} required></label>`;
 formDialog(old?'Edit roster member':'Add roster member',`<div class="form-grid">${field('Species','species',m.species)}<label>Nickname (optional)<input name="nickname" value="${esc(m.nickname)}"></label>${field('Level','level',m.level,'number')}${field('Cumulative XP','xp',m.xp_total,'number')}${field('Current HP','hp',m.resources[0].current,'number')}${field('Maximum HP','max',m.resources[0].max,'number')}<label>Status<select name="status"><option value="active" ${m.status==='active'?'selected':''}>Active</option><option value="boxed" ${m.status==='boxed'?'selected':''}>Boxed</option></select></label>${field('Ability · confirmed catch result','ability',m.ability)}${field('Bond band','bond',m.bond)}<label>Held item (blank for none)<input name="held" value="${esc(m.held_item||'')}"></label></div><h3>Six-stat block</h3><div class="form-grid">${m.stats.map((s,i)=>field('Stat label '+(i+1),'stat-label-'+i,s.label)+field('Value '+(i+1),'stat-value-'+i,s.value,'number')).join('')}</div><h3>Status condition</h3><label>Condition (blank for none)<input name="condition" value="${esc(m.status_condition?.name||'')}"></label><div class="form-grid"><label>Duration remaining (blank if unquantified)<input name="duration" type="number" min="0" step="1" value="${m.status_condition?.duration_remaining??''}"></label><label>Duration unit<input name="unit" value="${esc(m.status_condition?.duration_unit||'turns')}"></label></div><p class="small muted">Moves are managed individually after saving. Ability and bond are literal confirmed values; Scroll does not roll or calculate them.</p><label>Reason<input name="reason" required value="${old?'Correct roster details':'Add confirmed roster member'}"></label>`,f=>{m.species=String(f.get('species'));m.nickname=String(f.get('nickname'));m.level=Number(f.get('level'));m.xp_total=Number(f.get('xp'));m.status=String(f.get('status'));m.resources[0]={id:'hp',current:Number(f.get('hp')),max:Number(f.get('max'))};m.stats=m.stats.map((s,i)=>({...s,label:String(f.get('stat-label-'+i)),value:Number(f.get('stat-value-'+i))}));m.ability=String(f.get('ability'));m.bond=String(f.get('bond'));m.held_item=String(f.get('held')).trim()||null;m.status_condition=String(f.get('condition')).trim()?{name:String(f.get('condition')),duration_remaining:String(f.get('duration')).trim()===''?null:Number(f.get('duration')),duration_unit:String(f.get('unit'))}:null;const reason=String(f.get('reason'));review(preview(state,[{op:old?'set_roster_member':'add_roster_member',character_id:focus,member:m,reason}],reason));});}
function rosterCounter(id,moveID){const m=ownedMember(id),move=moveID?m.moves.find(a=>a.move_id===moveID):null;if(moveID&&!move)throw Error('Unknown move.');const label=move?'PP for '+move.name:'HP for '+(m.nickname||m.species);formDialog('Adjust '+label,`<p>Current ${move?move.pp_current:m.resources[0].current} / ${move?move.pp_max:m.resources[0].max}</p><label>Change (negative to spend / take damage)<input name="delta" type="number" step="1" required></label><p class="small muted">This creates a reviewed revision with an automatic manual-adjustment reason.</p>`,f=>{const delta=Number(f.get('delta')),reason='Manual '+label+' adjustment';review(preview(state,[{op:move?'adjust_move_pp':'adjust_roster_hp',character_id:focus,roster_id:m.roster_id,...(move?{move_id:move.move_id}:{}),delta,reason}],reason));});}
function rosterMove(id,moveID){const m=ownedMember(id),old=moveID?m.moves.find(a=>a.move_id===moveID):null;if(moveID&&!old)throw Error('Unknown move.');const move=old||{move_id:uid(),name:'',type:'',category:'',power:null,accuracy:null,pp_current:'',pp_max:'',effect:''};formDialog(old?'Edit move':'Add move',`<div class="form-grid">${['name','type','category','power','accuracy','pp_current','pp_max'].map(k=>`<label>${esc(k.replaceAll('_',' '))}<input name="${k}" value="${esc(move[k]??'')}" ${k.startsWith('pp_')?'type="number" min="0" step="1"':''} ${['power','accuracy'].includes(k)?'placeholder="Not yet quantified"':'required'}></label>`).join('')}</div><label>Effect<textarea name="effect" required>${esc(move.effect)}</textarea></label><label>Reason<input name="reason" required value="${old?'Update confirmed move':'Add confirmed move'}"></label>`,f=>{const next={...move};for(const k of ['name','type','category','effect'])next[k]=String(f.get(k));for(const k of ['power','accuracy'])next[k]=String(f.get(k)).trim()||null;for(const k of ['pp_current','pp_max'])next[k]=Number(f.get(k));if(old)m.moves[m.moves.findIndex(x=>x.move_id===old.move_id)]=next;else m.moves.push(next);const reason=String(f.get('reason'));review(preview(state,[{op:'set_roster_member',character_id:focus,member:m,reason}],reason));});}
function rosterConfig(){formDialog('Roster settings',`<label>Roster tab label<input name="label" required value="${esc(state.roster_config?.label||'Roster')}"></label><label>Roster XP table (level → cumulative XP or "unknown")<textarea class="mono" name="table">${esc(JSON.stringify(state.roster_level_thresholds||{},null,2))}</textarea></label><p class="small muted">Omitted existing levels remain unchanged. Trainer thresholds are separate.</p><label>Reason<input name="reason" required value="Confirm roster configuration"></label>`,f=>{const table=JSON.parse(String(f.get('table')));if(!table||typeof table!=='object'||Array.isArray(table))throw Error('Use a level-to-XP object.');const reason=String(f.get('reason'));const ops=[{op:'configure_roster',character_id:focus,label:String(f.get('label')),reason},...Object.entries(table).map(([level,cumulative_xp])=>{if(!/^[1-9]\d*$/.test(level))throw Error('Use whole level numbers.');return {op:'set_roster_level_threshold',character_id:focus,level:Number(level),cumulative_xp,reason};})];review(preview(state,ops,reason));});}
function trainerSnapshotDialog(){const snapshot=exportSnapshot(state,focus),text=JSON.stringify(snapshot,null,2),filename='scroll-trainer-snapshot.json',file=new File([text],filename,{type:'application/json'});showModal('Export snapshot for '+selected().name,'<p>Includes only this trainer’s info, roster (active and boxed), and inventory. No campaign history or hidden schedule.</p><p>The receiving player opens Scroll’s Trainer snapshot viewer and chooses this file. Each import replaces their previous read-only snapshot.</p><div class="actions"><button class="primary" id="download-snapshot">Download JSON</button><button id="share-snapshot">Share / Save to Files</button></div>','<div class="dialog-footer"><button data-close>Done</button></div>');$('#download-snapshot').onclick=()=>download(text,filename);const share=$('#share-snapshot');share.hidden=!navigator.canShare?.({files:[file]});share.onclick=async()=>{try{await navigator.share({files:[file],title:'Trainer snapshot'});}catch(e){if(e.name!=='AbortError')error(e);}};}

